-- Demo data for Pratishtha Bridal (generated by supabase/make-seed.js). Dates are relative to today.
-- Safe to run once on an empty database. It does NOT create users: sign up the owner first, then run this.
begin;
update shop_settings set shop_name='Pratishtha Bridal', address='12, Ring Road, Surat, Gujarat 395002', phone='98250 00000', upi_id='pratishthabridal@upi', salon_terms=array['An advance is needed to confirm the dates and is non-refundable.', 'The balance is payable before the first function of the wedding.', 'Trial is chargeable and is adjusted in the package if the booking is confirmed.', 'Artists are reserved for the booked times; extra time or extra people are charged separately.', 'Date changes depend on artist availability.'] where id=1;
select setval(pg_get_serial_sequence('customers', 'id'), (select max(id) from customers));
select setval(pg_get_serial_sequence('bookings', 'id'), greatest(1100, (select max(id) from bookings)));
select setval(pg_get_serial_sequence('artists', 'id'), (select max(id) from artists));
select setval(pg_get_serial_sequence('salon_services', 'id'), (select max(id) from salon_services));
select setval(pg_get_serial_sequence('wedding_events', 'id'), (select max(id) from wedding_events));
select setval(pg_get_serial_sequence('wedding_items', 'id'), (select max(id) from wedding_items));
select setval(pg_get_serial_sequence('wedding_tasks', 'id'), (select max(id) from wedding_tasks));
select setval(pg_get_serial_sequence('wedding_payments', 'id'), (select max(id) from wedding_payments));
select setval(pg_get_serial_sequence('weddings', 'id'), greatest(5001, (select max(id) from weddings)));
commit;
